-- `ALTER TABLE … ADD CONSTRAINT … UNIQUE` builds an index over the table's rows and is
-- refused as `CREATE INDEX` is, naming the constraint's index.
-- @setup
CREATE TABLE t (a text);
INSERT INTO t VALUES ('');
-- @test
-- @expect-error: the constraint build refuses an existing row
-- @expect-message
-- @profile-lock
ALTER TABLE t ADD CONSTRAINT t_u UNIQUE (a);
